org.machanism.machai.ai.provider.Genai provider = new org.machanism.machai.ai.provider.impl.OpenAIProvider();
provider.init("gpt-4.1", configurator);
provider.instructions("You are a helpful assistant.");
provider.prompt("Summarize the project architecture.");
java.lang.String answer = provider.perform();
provider.clear();

org.machanism.machai.ai.provider.Genai provider = new org.machanism.machai.ai.provider.impl.AnthropicProvider();
provider.init("claude-3-5-sonnet", configurator);
provider.prompt("Explain how tool registration works.");
