org.machanism.machai.ai.provider.impl.ToolsProvider provider = new org.machanism.machai.ai.provider.impl.ToolsProvider();
provider.init("yaml", configurator);
provider.addTools(functionTools);
provider.prompt("tool: myTool\nparams:\n  key: value");
java.lang.String result = provider.perform();

org.machanism.machai.ai.provider.Genai chat = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o", configurator);
chat.instructions("You are concise and precise.");
chat.prompt("List the public provider implementations.");
java.lang.String response = chat.perform();

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o", configurator);
provider.addTools(new com.example.ProjectTools());
provider.prompt("Use the available tools to inspect project metadata.");
java.lang.String answer = provider.perform();

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("Anthropic:claude-3-5-sonnet", configurator);
provider.prompt("Create a migration checklist for enabling embeddings.");
java.lang.String checklist = provider.perform();
provider.clear();

public final class ProjectTools implements org.machanism.machai.ai.tools.FunctionTools {
  @org.machanism.machai.ai.tools.Tool(description = "Return project status.")
  public java.lang.String status() {
    return "OK";
  }
}

org.machanism.machai.ai.provider.Genai provider = org.machanism.machai.ai.manager.GenaiProviderManager.getProvider("OpenAI:gpt-4o-mini", configurator);
